const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>[...p.querySelectorAll(s)];
const mode=document.body.dataset.mode||'phone';
const store=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(`one.${mode}.${key}`))??fallback}catch{return fallback}};
const save=(key,value)=>localStorage.setItem(`one.${mode}.${key}`,JSON.stringify(value));
const icons={notifications:'🔔',mail:'✉️',route:'↗️',household:'🧺',movies:'🎬',parking:'🅿️',settings:'⚙️',ask:'✦',recipes:'🍲',news:'📰',radio:'📻',currency:'⇄',finance:'€',lifestyle:'♥',whatsapp:'💬',googlehome:'⌂',music:'♫',theonecar:'◉',add:'＋'};
const phoneTiles=[['notifications','Meldingen','Eigen notities'],['mail','Mail & Kalender','Open je webmail'],['route','Route','Navigeren en tanken'],['household','Huishouden','Boodschappenlijst'],['movies','Films, Series & Muziek','Snel zoeken'],['parking','Parkeren','Timer en locatie'],['settings','Instellingen','Webapp voorkeuren'],['ask','Vraag het','Open ChatGPT'],['recipes','Recepten','Surinaams, Italiaans, Hollands'],['news','Nieuws','Vaste nieuwsbronnen'],['radio','Radio','Luister online'],['currency','Koers','EUR, USD en SRD'],['finance','Financiën','Budget bijhouden'],['lifestyle','Lifestyle','Bewegen en weer'],['whatsapp','WhatsApp','Open WhatsApp Web'],['googlehome','Google Home','Open Google Home']];
const carTiles=[['theonecar','The One Car','WhatsApp gesprekken'],['notifications','Meldingen','Ritnotities'],['mail','Mail & Kalender','Open webmail'],['route','Route','Google Maps'],['household','Huishouden','Boodschappen'],['music','Muziek','Radio of eigen audio'],['radio','Radio','Online stations'],['parking','Parkeren','Start parkeerwekker'],['news','Nieuws','Onderweg bijgepraat'],['settings','Instellingen','Dashboard voorkeuren'],['add','App toevoegen','Webkoppeling']];
let tiles=mode==='car'?reorder(carTiles):phoneTiles;
function reorder(list){const order=store('order',[]),map=Object.fromEntries(list.map(x=>[x[0],x]));return [...order.map(k=>map[k]).filter(Boolean),...list.filter(x=>!order.includes(x[0]))]}
function render(){const grid=$('#grid');grid.innerHTML='';tiles.forEach(([id,label,hint],i)=>{const b=document.createElement('button');b.className=`tile ${id==='theonecar'?'featured':''}`;b.dataset.id=id;b.innerHTML=`<span class="ico">${icons[id]||'◆'}</span><span><span class="label">${label}</span><span class="hint">${hint}</span></span>`;b.onclick=()=>openTool(id,label);if(mode==='car'&&id!=='add'){b.draggable=true;b.ondragstart=()=>{b.classList.add('dragging');b.dataset.from=i};b.ondragend=()=>b.classList.remove('dragging');b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();const from=Number($('.dragging')?.dataset.from);const moved=tiles.splice(from,1)[0];tiles.splice(i,0,moved);save('order',tiles.map(x=>x[0]));render()}}grid.append(b)})}
function panel(title,html){$('#panelTitle').textContent=title;$('#panelBody').innerHTML=html;$('#panel').classList.add('open');$('#panel').setAttribute('aria-hidden','false');$('#panelBody input, #panelBody button, #panelBody a')?.focus()}
function closePanel(){$('#panel').classList.remove('open');$('#panel').setAttribute('aria-hidden','true')}
function openTool(id,title){const actions={notifications:notes,mail:mail,route:route,household:shopping,movies:movies,parking:parking,settings:settings,ask:()=>open('https://chatgpt.com/','_blank'),recipes:recipes,news:news,radio:radio,currency:currency,finance:finance,lifestyle:lifestyle,whatsapp:()=>open('https://web.whatsapp.com/','_blank'),googlehome:()=>open('https://home.google.com/','_blank'),music:music,theonecar:()=>open('https://web.whatsapp.com/','_blank'),add:addLink};(actions[id]||(()=>panel(title,'<p class="notice">Deze functie is beschikbaar in de Android-app.</p>')))()}
function notes(){let data=store('notes',[]);panel('Meldingen',`<form id="noteForm" class="row"><input class="field" name="text" placeholder="Nieuwe notitie" required><button class="btn">Toevoegen</button></form><div class="list" id="notes"></div>`);const draw=()=>$('#notes').innerHTML=data.length?data.map((n,i)=>`<div class="item"><span>${escapeHtml(n)}</span><button class="btn danger" data-i="${i}">Wis</button></div>`).join(''):'<p class="notice">Nog geen meldingen.</p>';draw();$('#noteForm').onsubmit=e=>{e.preventDefault();data.unshift(new FormData(e.target).get('text'));save('notes',data);notes()};$('#notes').onclick=e=>{if(e.target.dataset.i!==undefined){data.splice(+e.target.dataset.i,1);save('notes',data);notes()}}}
function mail(){panel('Mail & Kalender',`<div class="links"><a class="link" target="_blank" href="https://mail.google.com/">✉️ Gmail</a><a class="link" target="_blank" href="https://calendar.google.com/">📅 Google Kalender</a><a class="link" target="_blank" href="https://outlook.live.com/mail/">✉️ Outlook</a><a class="link" target="_blank" href="https://outlook.live.com/calendar/">📅 Outlook Kalender</a></div>`)}
function route(){panel('Route',`<form id="routeForm" class="stack"><input class="field" name="to" placeholder="Waar wil je naartoe?" required><button class="btn">Open in Google Maps</button><button type="button" class="btn secondary" id="waze">Open in Waze</button></form>`);const go=base=>{const q=encodeURIComponent(new FormData($('#routeForm')).get('to'));if(!q)return;open(base.replace('{q}',q),'_blank')};$('#routeForm').onsubmit=e=>{e.preventDefault();go('https://www.google.com/maps/dir/?api=1&destination={q}')};$('#waze').onclick=()=>go('https://waze.com/ul?q={q}&navigate=yes')}
function shopping(){let items=store('shopping',[]);panel('Boodschappenlijst',`<form id="shopForm" class="row"><input class="field" name="item" placeholder="Wat heb je nodig?" required><button class="btn">Voeg toe</button></form><div class="list" id="shopList"></div>`);const draw=()=>$('#shopList').innerHTML=items.length?items.map((x,i)=>`<label class="item"><span><input type="checkbox" data-check="${i}" ${x.done?'checked':''}> ${escapeHtml(x.text)}</span><button class="btn danger" data-del="${i}">Wis</button></label>`).join(''):'<p class="notice">Je lijst is leeg.</p>';draw();$('#shopForm').onsubmit=e=>{e.preventDefault();items.push({text:new FormData(e.target).get('item'),done:false});save('shopping',items);shopping()};$('#shopList').onchange=e=>{const i=e.target.dataset.check;if(i!==undefined){items[i].done=e.target.checked;save('shopping',items)}};$('#shopList').onclick=e=>{const i=e.target.dataset.del;if(i!==undefined){items.splice(i,1);save('shopping',items);shopping()}}}
function movies(){panel('Films, Series & Muziek',`<form id="mediaForm" class="stack"><input class="field" name="q" placeholder="Titel of artiest" required><select class="field" name="site"><option value="https://www.youtube.com/results?search_query=">YouTube</option><option value="https://www.pathe.nl/zoek?q=">Pathé</option><option value="https://www.themoviedb.org/search?query=">The Movie Database</option></select><button class="btn">Zoeken</button></form>`);$('#mediaForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);open(f.get('site')+encodeURIComponent(f.get('q')),'_blank')}}
function parking(){let end=store('parkingEnd',0);panel('Parkeren',`<div id="parkingState"></div><div class="row"><input id="minutes" class="field" type="number" min="1" value="60"><button id="startParking" class="btn">Start timer</button><button id="stopParking" class="btn danger">Stop</button></div>`);const draw=()=>{const left=Math.max(0,end-Date.now());$('#parkingState').innerHTML=left?`<p class="metric">${Math.ceil(left/60000)} min</p><p class="notice">Je parkeerwekker loopt.</p>`:'<p class="notice">Er loopt geen parkeerwekker.</p>'};draw();$('#startParking').onclick=()=>{end=Date.now()+(+$('#minutes').value||60)*60000;save('parkingEnd',end);draw()};$('#stopParking').onclick=()=>{end=0;save('parkingEnd',0);draw()}}
function settings(){panel('Instellingen',`<div class="stack"><label class="item"><span>Grote tegels</span><input id="largeTiles" type="checkbox" ${store('large',false)?'checked':''}></label><button id="resetData" class="btn danger">Wis alleen gegevens van deze webapp</button></div>`);$('#largeTiles').onchange=e=>{save('large',e.target.checked);document.documentElement.style.fontSize=e.target.checked?'19px':''};$('#resetData').onclick=()=>{if(confirm('Webappgegevens wissen?')){Object.keys(localStorage).filter(k=>k.startsWith(`one.${mode}.`)).forEach(k=>localStorage.removeItem(k));location.reload()}}}
function recipes(){panel('Recepten',`<div class="links"><a class="link" target="_blank" href="https://sranangkukru.net/recepten/">🇸🇷 Sranang Kukru</a><a class="link" target="_blank" href="https://www.leukerecepten.nl/italiaanse-recepten/">🇮🇹 Italiaans</a><a class="link" target="_blank" href="https://www.leukerecepten.nl/hollandse-recepten/">🇳🇱 Hollands</a><a class="link" target="_blank" href="https://chatgpt.com/">✦ Vraag om een recept</a></div>`)}
function news(){panel('Nieuws',`<div class="links">${[['Starnieuws','https://www.starnieuws.com/'],['Waterkant','https://www.waterkant.net/'],['NU.nl','https://www.nu.nl/'],['NOS','https://nos.nl/'],['De Ware Tijd','https://dwtonline.com/']].map(x=>`<a class="link" target="_blank" href="${x[1]}">${x[0]}</a>`).join('')}</div>`)}
function radio(){panel('Radio',`<div class="links">${[['Radio 538','https://www.538.nl/radio/luisteren'],['FunX','https://www.funx.nl/'],['Sky Radio','https://www.skyradio.nl/'],['Soul Radio','https://soulradio.nl/'],['Radio Veronica','https://www.radioveronica.nl/'],['Qmusic','https://www.qmusic.nl/']].map(x=>`<a class="link" target="_blank" href="${x[1]}">▶ ${x[0]}</a>`).join('')}</div>`)}
async function currency(){panel('Koers',`<p class="notice">Actuele indicatie per €1.</p><div id="rates" class="stack"><p>Koersen laden…</p></div>`);try{const r=await fetch('https://open.er-api.com/v6/latest/EUR');const d=await r.json();$('#rates').innerHTML=`<div class="item"><span>EUR → USD</span><strong>${d.rates.USD?.toFixed(4)}</strong></div><div class="item"><span>EUR → SRD</span><strong>${d.rates.SRD?.toFixed(4)}</strong></div>`}catch{$('#rates').innerHTML='<p class="notice">Koersen konden nu niet worden geladen.</p>'}}
function finance(){let entries=store('finance',[]),budget=store('budget',0);panel('Financiën',`<div class="item"><span>Maandbudget</span><strong>€ <input id="budget" class="field" style="width:120px" type="number" step="0.01" value="${budget}"></strong></div><form id="moneyForm" class="row"><input class="field" name="desc" placeholder="Omschrijving" required><input class="field" name="amount" type="number" step="0.01" placeholder="Bedrag" required><button class="btn">Boek</button></form><div id="moneyList" class="list"></div>`);const draw=()=>{const spent=entries.reduce((s,x)=>s+x.amount,0);$('#moneyList').innerHTML=`<div class="item"><span>Uitgegeven</span><strong>€ ${spent.toFixed(2)}</strong></div><div class="item"><span>Over</span><strong>€ ${(budget-spent).toFixed(2)}</strong></div>`+entries.map((x,i)=>`<div class="item"><span>${escapeHtml(x.desc)}</span><span>€ ${x.amount.toFixed(2)} <button class="btn danger" data-i="${i}">Wis</button></span></div>`).join('')};draw();$('#budget').onchange=e=>{budget=+e.target.value||0;save('budget',budget);draw()};$('#moneyForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);entries.unshift({desc:f.get('desc'),amount:+f.get('amount')});save('finance',entries);finance()};$('#moneyList').onclick=e=>{if(e.target.dataset.i!==undefined){entries.splice(+e.target.dataset.i,1);save('finance',entries);finance()}}}
function lifestyle(){panel('Lifestyle',`<div class="links"><a class="link" target="_blank" href="https://www.buienradar.nl/weer/almere/nl/2759879">☁ Weer in Almere</a><a class="link" target="_blank" href="https://www.google.com/maps/search/wandelroute+Almere">🚶 Wandelroutes</a></div>`)}
function music(){panel('Muziek',`<div class="stack"><input id="audioFiles" class="field" type="file" accept="audio/*" multiple><audio id="player" controls style="width:100%"></audio><button id="openRadio" class="btn secondary">Open radiozenders</button></div>`);$('#audioFiles').onchange=e=>{const f=e.target.files[0];if(f)$('#player').src=URL.createObjectURL(f)};$('#openRadio').onclick=radio}
function addLink(){panel('App toevoegen',`<form id="linkForm" class="stack"><input class="field" name="name" placeholder="Naam" required><input class="field" name="url" type="url" placeholder="https://…" required><button class="btn">Open koppeling</button></form><p class="notice">De browserversie opent de koppeling direct. Aangepaste tegels blijven een Android-functie.</p>`);$('#linkForm').onsubmit=e=>{e.preventDefault();open(new FormData(e.target).get('url'),'_blank')}}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function tick(){const d=new Date();$('#clock').textContent=d.toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'})}tick();setInterval(tick,30000);$('#closePanel').onclick=closePanel;$('#panel').onclick=e=>{if(e.target.id==='panel')closePanel()};document.onkeydown=e=>{if(e.key==='Escape')closePanel()};if(store('large',false))document.documentElement.style.fontSize='19px';render();
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'open_the_one_feature',title:'Open The One functie',description:'Open een tegel in de zichtbare The One webapp.',inputSchema:{type:'object',properties:{feature:{type:'string'}},required:['feature'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute({feature}){const tile=tiles.find(t=>t[0]===feature);if(!tile)throw new Error('Onbekende functie');openTool(tile[0],tile[1]);return{opened:tile[0]}}}).catch(()=>{})}
